package ledger

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Refactoring log:
//
//  1. Replaced the hand-rolled selection sort (with the m1/m2 boolean encoding)
//     with sort.Slice using an explicit (date, description, change) comparison.
//     The sort operates on a copy so the caller's slice is never mutated.
//  2. Removed the recursive self-call used to validate an empty ledger and the
//     goroutine/channel fan-out; entries are now formatted sequentially into a
//     strings.Builder, which also makes error handling straightforward.
//  3. Validated the currency and locale up front and extracted the
//     locale-specific concerns (header, date layout, amount layout) into small
//     helper functions.
//  4. Extracted amount formatting (thousands/decimal separators plus the
//     positive/negative markers) into formatAmount and date formatting into
//     displayDate, each of which validates its own input.
//  5. Replaced the manual column padding with rune-aware padLeft/padRight
//     helpers so multi-byte characters (e.g. the euro sign) align correctly.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// FormatLedger renders the given entries as a formatted ledger for the
// provided currency and locale.
func FormatLedger(currency, locale string, entries []Entry) (string, error) {
	symbol, err := currencySymbol(currency)
	if err != nil {
		return "", err
	}
	header, err := header(locale)
	if err != nil {
		return "", err
	}

	// Sort a copy of the entries so the caller's slice is left untouched.
	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		a, b := sorted[i], sorted[j]
		if a.Date != b.Date {
			return a.Date < b.Date
		}
		if a.Description != b.Description {
			return a.Description < b.Description
		}
		return a.Change < b.Change
	})

	var b strings.Builder
	b.WriteString(header)
	for _, e := range sorted {
		line, err := formatLine(symbol, locale, e)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}

// currencySymbol maps a currency code to its symbol, rejecting unknown codes.
func currencySymbol(currency string) (string, error) {
	switch currency {
	case "USD":
		return "$", nil
	case "EUR":
		return "€", nil
	default:
		return "", fmt.Errorf("invalid currency %q", currency)
	}
}

// header returns the locale-specific column header line.
func header(locale string) (string, error) {
	switch locale {
	case "en-US":
		return fmt.Sprintf("%-10s | %-25s | %s\n", "Date", "Description", "Change"), nil
	case "nl-NL":
		return fmt.Sprintf("%-10s | %-25s | %s\n", "Datum", "Omschrijving", "Verandering"), nil
	default:
		return "", fmt.Errorf("invalid locale %q", locale)
	}
}

// formatLine renders a single entry as a ledger line.
func formatLine(symbol, locale string, e Entry) (string, error) {
	date, err := displayDate(locale, e.Date)
	if err != nil {
		return "", err
	}
	desc := truncateDescription(e.Description)
	amount := formatAmount(symbol, locale, e.Change)
	return padRight(date, 10) + " | " + padRight(desc, 25) + " | " + padLeft(amount, 13) + "\n", nil
}

// displayDate validates an ISO "Y-m-d" date and lays it out for the locale.
func displayDate(locale, date string) (string, error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", fmt.Errorf("invalid date %q", date)
	}
	year, month, day := date[0:4], date[5:7], date[8:10]
	switch locale {
	case "nl-NL":
		return day + "-" + month + "-" + year, nil
	default: // en-US
		return month + "/" + day + "/" + year, nil
	}
}

// truncateDescription shortens descriptions longer than the 25-column field.
func truncateDescription(desc string) string {
	if utf8.RuneCountInString(desc) > 25 {
		runes := []rune(desc)
		desc = string(runes[:22]) + "..."
	}
	return desc
}

// formatAmount renders a cent value using the locale's number conventions.
func formatAmount(symbol, locale string, change int) string {
	negative := change < 0
	if negative {
		change = -change
	}
	dollars, cents := change/100, change%100

	var amount string
	switch locale {
	case "nl-NL":
		amount = fmt.Sprintf("%s %s,%02d", symbol, groupThousands(dollars, '.'), cents)
		if negative {
			amount += "-"
		} else {
			amount += " "
		}
	default: // en-US
		amount = fmt.Sprintf("%s%s.%02d", symbol, groupThousands(dollars, ','), cents)
		if negative {
			amount = "(" + amount + ")"
		} else {
			amount += " "
		}
	}
	return amount
}

// groupThousands inserts a thousands separator every three digits.
func groupThousands(n int, sep byte) string {
	s := strconv.Itoa(n)
	var b strings.Builder
	for i, c := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteByte(sep)
		}
		b.WriteRune(c)
	}
	return b.String()
}

// padLeft right-justifies s within width runes.
func padLeft(s string, width int) string {
	if n := utf8.RuneCountInString(s); n >= width {
		return s
	}
	return strings.Repeat(" ", width-n) + s
}

// padRight left-justifies s within width runes.
func padRight(s string, width int) string {
	if n := utf8.RuneCountInString(s); n >= width {
		return s
	}
	return s + strings.Repeat(" ", width-n)
}

